describe('ToolRegistry input validation', () => {
  it('returns a rejection when a required property is missing', async () => {
    const registry = new ToolRegistry();
    const execute = jest.fn(async () => 'sunny');
    registry.register(
      {
        name: 'get_weather',
        description: 'Get weather for a location',
        inputSchema: {
          type: 'object',
          properties: {location: {type: 'string'}},
          required: ['location'],
        },
      },
      execute
    );

    const response = await registry.execute('get_weather', {});
    const executorCalls = execute.mock.calls;

    expect({result: response.result, executorCalls: executorCalls.length}).toEqual({
      result: "Input validation failed: required property 'location' is missing",
      executorCalls: 0,
    });
  });

  it('describes a wrong property type without exposing its value', async () => {
    const registry = new ToolRegistry();
    let executorCalls = 0;
    registry.register(
      {
        name: 'find_customer',
        description: 'Find a customer',
        inputSchema: {
          type: 'object',
          properties: {customerId: {type: 'string'}},
          required: ['customerId'],
        },
      },
      async () => {
        executorCalls += 1;
        return 'found';
      }
    );

    const response = await registry.execute('find_customer', {customerId: 123456789});

    expect({result: response.result, executorCalls}).toEqual({
      result: "Input validation failed: property '/customerId' must be string",
      executorCalls: 0,
    });
  });
});

